import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class TradeOffDemonstrator {
    private final ExecutorService executor = new ThreadPoolExecutor(
        4, 200, 60L, TimeUnit.SECONDS,
        new ArrayBlockingQueue<>(1000),
        new ThreadPoolExecutor.CallerRunsPolicy()
    );
    private final AtomicInteger activeRequests = new AtomicInteger(0);

    public CompletableFuture<String> processRequest(String payload) {
        int currentLoad = activeRequests.incrementAndGet();
        // Graceful degradation / Availability trade-off: Shed load if queue/concurrency is too high
        if (currentLoad > 150) {
            activeRequests.decrementAndGet();
            return CompletableFuture.completedFuture("Service Unavailable - Shedding Load");
        }

        return CompletableFuture.supplyAsync(() -> {
            try {
                // Simulate processing latency vs throughput work
                Thread.sleep(10);
                return "Processed: " + payload;
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new CompletionException(e);
            } finally {
                activeRequests.decrementAndGet();
            }
        }, executor);
    }
}
